  if ($code -notmatch '^\d{6}$' -or [string]::IsNullOrWhiteSpace($name)) { continue }

  $cap = Num $item.f20
  $flow = Num $item.f62
  $capYi = if ($null -ne $cap) { {0:F2}" -f ($cap / 100000000) } else { "" }

) | Out-Null
