$top5 = $stockObjects |
  Where-Object {
    (-not $_.TrackingOnly) -and
    (-not $_.IsST) -and
    ($null -ne $_.CapYi -and $_.CapYi -ge 100) -and
    ($null -eq $_.LossYears -or $_.LossYears -lt 3) -and
    ($null -ne $_.VolumeRatio -and $_.VolumeRatio -ge 0.3) -and
    ($null -ne $_.Turnover -and $_.Turnover -ge 0.3) -and
    ($null -ne $_.Change -and $_.Change -ge -5 -and $_.Change -le 9)
  } |
  ForEach-Object {
    $_ | Add-Member -NotePropertyName Score -NotePropertyValue (Get-ShortScore $_) -Force
    $_
  } |
  Sort-Object Score -Descending |
  Select-Object -First 5

$newSimLines = New-Object System.Collections.Generic.List[string]
$rank = 1
